module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg load;
    reg ena;
    reg [1:0] amount;
    reg [63:0] data;
    wire [63:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .amount(amount),
        .data(data),
        .q(q)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    reg [63:0] expected;

    // Task to apply reset/load initial value
    task load_value(input [63:0] initial_data);
        begin
            @(posedge clk);
            load = 1'b1;
            ena = 1'b0;
            data = initial_data;
            amount = 2'b00;
            @(posedge clk);
            load = 1'b0;
        end
    endtask

    // Task to execute a shift and check
    task check_shift(input [1:0] shift_amt, input [63:0] exp_val);
        begin
            @(posedge clk);
            load = 1'b0;
            ena = 1'b1;
            amount = shift_amt;
            expected = exp_val;
            // Wait slightly after clock edge to check
            #1;
            if (q !== expected) begin
                $display("FAIL: Time=%0t | amt=%b, q=%h, expected=%h", $time, shift_amt, q, expected);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        load = 0;
        ena = 0;
        amount = 0;
        data = 0;
        expected = 0;
        #12;

        // Test 1: Synchronous Load
        load_value(64'h0000_0000_0000_0001);
        #1;
        if (q !== 64'h0000_0000_0000_0001) begin
            $display("FAIL: Load failed. q=%h", q);
            errors = errors + 1;
        end

        // Test 2: Shift Left by 1 (Amount: 2'b00)
        // 1 << 1 = 2
        check_shift(2'b00, 64'h0000_0000_0000_0002);

        // Test 3: Shift Left by 8 (Amount: 2'b01)
        // 2 << 8 = 512 (0x200)
        check_shift(2'b01, 64'h0000_0000_0000_0200);

        // Test 4: Disable enable signal (should hold state)
        @(posedge clk);
        ena = 1'b0;
        #1;
        if (q !== 64'h0000_0000_0000_0200) begin
            $display("FAIL: Ena=0 hold state failed. q=%h", q);
            errors = errors + 1;
        end

        // Test 5: Arithmetic Right Shift by 1 with positive number (Amount: 2'b10)
        load_value(64'h0000_0000_0000_0400);
        check_shift(2'b10, 64'h0000_0000_0000_0200);

        // Test 6: Arithmetic Right Shift by 8 with positive number (Amount: 2'b11)
        // 0x200 >> 8 = 0x2
        check_shift(2'b11, 64'h0000_0000_0000_0002);

        // Test 7: Arithmetic Right Shift with sign extension (negative number)
        // Load negative number (MSB = 1)
        load_value(64'h8000_0000_0000_0000);
        // Shift right by 1 (Amount: 2'b10), should sign extend: 0xC000_0000_0000_0000
        check_shift(2'b10, 64'hC000_0000_0000_0000);

        // Test 8: Arithmetic Right Shift by 8 with sign extension (Amount: 2'b11)
        // 0xC000_0000_0000_0000 >> 8 -> 0xFFC0_0000_0000_0000
        check_shift(2'b11, 64'hFFC0_0000_0000_0000);

        // Final Result Display
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
